/**
 * Jinx Cannibal + Zealot: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Cannibal
 * Wiki: https://wiki.bloodontheclocktower.com/Zealot
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`. Each test quotes the wiki text it encodes word
 * for word in a `// Wiki: "..."` comment (CLAUDE.md, Trevor 2026-11-01 and 2026-11-02).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong, type Script } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { withGainedSteps } from '#lib/core/rules/abilities/gained-abilities.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes/jinx-pairs.ts';
import { nightStepAlerts } from '#lib/core/rules/night/night-alerts.ts';

const scriptOf = (ids: string[]): Script => ({
	meta: { name: 'Jinxed' },
	entries: ids.map((id) => ({ kind: 'official' as const, id }))
});
const script = scriptOf(['cannibal', 'zealot', 'saint', 'imp', 'chef', 'empath']);

/** The steps a gained ability adds tonight. */
const gainedSteps = (s: Scenario) =>
	withGainedSteps([], s.game, s.characters, 'other').filter((step) => step.gained);

describe('Cannibal + Zealot jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'cannibal', 'zealot');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('cannibal')?.name).toBe('Cannibal');
		expect(data.byId.get('zealot')?.name).toBe('Zealot');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['cannibal', 'zealot'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['cannibal'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['zealot'])).not.toContain(jinx);
	});

	describe('the Cannibal who gains the Zealot ability learns it', () => {
		const eaten = scenario(['cannibal', 'zealot', 'imp', 'chef', 'empath'], { script })
			.execute('zealot')
			.reminder('zealot', 'cannibal', 'Lunch');

		it("is data in the Cannibal's rules", () => {
			expect(jinxRulesBetween('cannibal', 'zealot', committedCharacters())).toEqual({
				learns: { what: 'ability' }
			});
		});

		it('the Zealot has no night text, so a step of its own wakes the Cannibal to learn it', () => {
			// Wiki: "If the Cannibal gains the Zealot ability, the Cannibal learns this."
			expect(eaten.characters.get('zealot')?.otherNightReminder).toBeUndefined();
			const steps = gainedSteps(eaten);
			expect(steps).toHaveLength(1);
			expect(steps[0]).toMatchObject({
				id: `cannibal@${eaten.seat('cannibal')}:zealot`,
				reminder: 'Wake the Cannibal: they learn they have the Zealot ability.',
				gained: { characterId: 'zealot', learns: 'ability' }
			});
			expect(steps[0].gained?.firstNightText).toBeUndefined();
			const alerts = nightStepAlerts(eaten.game, 'cannibal', eaten.characters);
			expect(alerts.filter((a) => a.kind === 'learns-gained')).toMatchObject([
				{ seatId: eaten.seat('cannibal'), source: { characterId: 'zealot' }, learns: 'ability' }
			]);
		});

		it('no step on a later night: the Zealot ability still never wakes them', () => {
			// Wiki: "If the Cannibal gains the Zealot ability, the Cannibal learns this."
			expect(gainedSteps(eaten.newDay().dusk())).toEqual([]);
		});

		it('without the jinx, an ability with no night text adds no step (the Saint)', () => {
			// Wiki: "The Cannibal is not told which ability they have gained. They must figure that
			// out for themselves."
			const saint = scenario(['cannibal', 'saint', 'imp', 'chef', 'empath'], { script })
				.execute('saint')
				.reminder('saint', 'cannibal', 'Lunch');
			expect(gainedSteps(saint)).toEqual([]);
		});
	});
});
